//! The AAPCS64 `va_list` and the variadic entry point stubs.
//!
//! On AArch64 a `va_list` is a structure describing where the caller's
//! arguments are: the register save areas for the 8 general and 8
//! floating-point argument registers (`__gr_top`/`__vr_top` point at
//! their ends, the offsets are negative and count up to zero) and the
//! stack (`__stack`). The stubs generated by [`variadic_stub!`] spill
//! `x0`-`x7` and `q0`-`q7` and build that structure, then call the `v*`
//! implementation with it appended to the fixed arguments.
//!
//! `long double` is IEEE binary128 here; it is passed in `q` registers
//! and converted to `f64` on read.

use core::ffi::c_void;

/// `va_list` (`struct __va_list`).
#[repr(C)]
pub struct VaList {
    stack: *mut u8,
    gr_top: *mut u8,
    vr_top: *mut u8,
    gr_offs: i32,
    vr_offs: i32,
}

impl VaList {
    /// Reads the next integer or pointer argument.
    ///
    /// # Safety
    /// The caller must have supplied such an argument.
    #[inline]
    pub unsafe fn gp(&mut self) -> u64 {
        // SAFETY: the areas were laid out by the stub / the C compiler.
        unsafe {
            if self.gr_offs < 0 {
                let p = self.gr_top.offset(self.gr_offs as isize) as *const u64;
                self.gr_offs += 8;
                *p
            } else {
                let v = *(self.stack as *const u64);
                self.stack = self.stack.add(8);
                v
            }
        }
    }

    /// Reads the next `double` argument.
    ///
    /// # Safety
    /// The caller must have supplied such an argument.
    #[inline]
    pub unsafe fn fp(&mut self) -> f64 {
        // SAFETY: as in `gp`.
        unsafe {
            if self.vr_offs < 0 {
                let p = self.vr_top.offset(self.vr_offs as isize) as *const f64;
                self.vr_offs += 16;
                *p
            } else {
                let v = *(self.stack as *const f64);
                self.stack = self.stack.add(8);
                v
            }
        }
    }

    /// Reads the next `long double` (binary128) argument, converted to
    /// `f64`.
    ///
    /// # Safety
    /// The caller must have supplied such an argument.
    #[inline]
    pub unsafe fn long_double(&mut self) -> f64 {
        // SAFETY: as in `gp`; a quad occupies one full `q` slot or 16
        // aligned stack bytes.
        unsafe {
            let bits = if self.vr_offs < 0 {
                let p = self.vr_top.offset(self.vr_offs as isize) as *const u128;
                self.vr_offs += 16;
                *p
            } else {
                let p = ((self.stack as usize + 15) & !15) as *const u128;
                self.stack = (p as *mut u8).add(16);
                *p
            };
            f128_to_f64(bits)
        }
    }

    /// Reads the next pointer argument.
    ///
    /// # Safety
    /// The caller must have supplied such an argument.
    #[inline]
    pub unsafe fn ptr(&mut self) -> *mut c_void {
        // SAFETY: forwarded.
        unsafe { self.gp() as usize as *mut c_void }
    }
}

/// Converts an IEEE binary128 value to `f64` (round to nearest even).
pub fn f128_to_f64(bits: u128) -> f64 {
    let sign = ((bits >> 127) as u64) << 63;
    let exp = ((bits >> 112) & 0x7fff) as i32;
    let mant = bits & ((1u128 << 112) - 1);
    if exp == 0x7fff {
        return f64::from_bits(sign | 0x7ff0_0000_0000_0000 | if mant != 0 { 1 << 51 } else { 0 });
    }
    if exp == 0 && mant == 0 {
        return f64::from_bits(sign);
    }
    // Exact value: (1.mant or 0.mant) * 2^(exp - 16383).
    let (m, e) = if exp == 0 { (mant, -16382) } else { (mant | (1u128 << 112), exp - 16383) };
    // Normalise so the leading one is at bit 112.
    let shift = m.leading_zeros() as i32 - 15;
    let m = m << shift;
    let e = e - shift;
    // Target: 53 significant bits; exponent range of f64.
    let e64 = e + 1023;
    if e64 >= 0x7ff {
        return f64::from_bits(sign | 0x7ff0_0000_0000_0000);
    }
    let (keep, e64) = if e64 <= 0 { (52 + e64 as i32, 0) } else { (53, e64) };
    if keep <= 0 {
        return f64::from_bits(sign);
    }
    let drop = 113 - keep;
    let mut frac = (m >> drop) as u64;
    let rem = m & ((1u128 << drop) - 1);
    let half = 1u128 << (drop - 1);
    if rem > half || (rem == half && frac & 1 == 1) {
        frac += 1;
    }
    let bits = if e64 == 0 {
        // Subnormal (a carry into bit 52 becomes the smallest normal).
        frac
    } else {
        ((e64 as u64) << 52) | (frac & ((1 << 52) - 1)) + (((frac >> 53) & 1) << 52) * 0
    };
    let bits = if e64 != 0 && frac >> 53 != 0 { ((e64 as u64 + 1) << 52) | 0 } else { bits };
    f64::from_bits(sign | bits)
}

/// Converts an `f64` to IEEE binary128 bits (exact).
pub fn f64_to_f128(x: f64) -> u128 {
    let b = x.to_bits();
    let sign = ((b >> 63) as u128) << 127;
    let exp = ((b >> 52) & 0x7ff) as i32;
    let mant = (b & ((1 << 52) - 1)) as u128;
    if exp == 0x7ff {
        return sign | (0x7fffu128 << 112) | if mant != 0 { 1u128 << 111 } else { 0 };
    }
    if exp == 0 {
        if mant == 0 {
            return sign;
        }
        // Subnormal double: normalise.
        let shift = mant.leading_zeros() as i32 - (128 - 53);
        let m = (mant << shift) & ((1u128 << 52) - 1);
        let e = 1 - 1023 - shift + 16383;
        return sign | ((e as u128) << 112) | (m << 60);
    }
    sign | (((exp - 1023 + 16383) as u128) << 112) | (mant << 60)
}

/// Generates a variadic C entry point `$name` with `$fixed` fixed integer
/// arguments that calls `$target` with a `va_list` pointer in `$reg`.
#[cfg(not(test))]
macro_rules! variadic_stub {
    ($name:ident, $fixed:literal, $reg:literal, $target:path) => {
        core::arch::global_asm!(
            concat!(".globl ", stringify!($name)),
            concat!(".type ", stringify!($name), ",%function"),
            concat!(stringify!($name), ":"),
            // Frame: 64 bytes of x0-x7, 128 bytes of q0-q7, 32 bytes of
            // va_list, 16 bytes for fp/lr.
            "stp x29, x30, [sp, #-240]!",
            "mov x29, sp",
            "stp x0, x1, [sp, #16]",
            "stp x2, x3, [sp, #32]",
            "stp x4, x5, [sp, #48]",
            "stp x6, x7, [sp, #64]",
            "stp q0, q1, [sp, #80]",
            "stp q2, q3, [sp, #112]",
            "stp q4, q5, [sp, #144]",
            "stp q6, q7, [sp, #176]",
            // va_list at sp+208: stack = caller's sp (sp+240),
            // gr_top = sp+80, vr_top = sp+208, gr_offs = -(8-fixed)*8,
            // vr_offs = -128.
            "add x9, sp, #240",
            "str x9, [sp, #208]",
            "add x9, sp, #80",
            "str x9, [sp, #216]",
            "add x9, sp, #208",
            "str x9, [sp, #224]",
            concat!("mov w9, #-(8 - ", $fixed, ") * 8"),
            "str w9, [sp, #232]",
            "mov w9, #-128",
            "str w9, [sp, #236]",
            concat!("add ", $reg, ", sp, #208"),
            "bl {target}",
            "ldp x29, x30, [sp], #240",
            "ret",
            concat!(".size ", stringify!($name), ", .-", stringify!($name)),
            target = sym $target,
        );
    };
}
#[cfg(not(test))]
pub(crate) use variadic_stub;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn f128_conversions_round_trip() {
        for x in [0.0, -0.0, 1.0, -2.5, 3.141592653589793, 1e300, 1e-300, 5e-324, f64::MAX, f64::MIN_POSITIVE, f64::INFINITY, f64::NEG_INFINITY] {
            let back = f128_to_f64(f64_to_f128(x));
            assert_eq!(back.to_bits(), x.to_bits(), "{x}");
        }
        assert!(f128_to_f64(f64_to_f128(f64::NAN)).is_nan());
        // One third in binary128 (more precise than a double) rounds to 1/3.
        let third: u128 = 0x3ffd5555555555555555555555555555;
        assert_eq!(f128_to_f64(third), 1.0 / 3.0);
        // Overflow and underflow saturate.
        assert_eq!(f128_to_f64(0x43ff << 112), f64::INFINITY);
        assert_eq!(f128_to_f64(0x0001 << 112), 0.0);
    }
}
